// HR-12 fan-out — verify X-HR-Signature. n8n parses the JSON body, so we rebuild the EXACT
// canonical bytes ERPNext signed: json.dumps(sort_keys=True, separators=(',',':'), ensure_ascii=True).
const crypto = require('crypto');
const item = items[0];
let ev;
if (item.binary && item.binary.data) { ev = JSON.parse(Buffer.from(item.binary.data.data,'base64').toString('utf8')); }
else if (typeof item.json.body === 'string') { ev = JSON.parse(item.json.body); }
else { ev = item.json.body || item.json; }
function pyStr(s){let o='"';for(const ch of s){const c=ch.codePointAt(0);
  if(ch==='"')o+='\\"';else if(ch==='\\')o+='\\\\';
  else if(c===8)o+='\\b';else if(c===9)o+='\\t';else if(c===10)o+='\\n';else if(c===12)o+='\\f';else if(c===13)o+='\\r';
  else if(c<32)o+='\\u'+c.toString(16).padStart(4,'0');
  else if(c<128)o+=ch;
  else if(c>0xffff){const h=Math.floor((c-0x10000)/0x400)+0xd800,l=((c-0x10000)%0x400)+0xdc00;o+='\\u'+h.toString(16).padStart(4,'0')+'\\u'+l.toString(16).padStart(4,'0');}
  else o+='\\u'+c.toString(16).padStart(4,'0');}
  return o+'"';}
function canon(v){if(v===null)return 'null';if(typeof v==='boolean')return v?'true':'false';if(typeof v==='number')return String(v);if(typeof v==='string')return pyStr(v);if(Array.isArray(v))return '['+v.map(canon).join(',')+']';const k=Object.keys(v).sort();return '{'+k.map(x=>pyStr(x)+':'+canon(v[x])).join(',')+'}';}
const headers = item.json.headers || {};
const got = headers['x-hr-signature'] || headers['X-HR-Signature'] || '';
const key = $env.HR_LIFECYCLE_SIGNING_KEY || '';
if (key) {
  const want = crypto.createHmac('sha256', key).update(canon(ev),'utf8').digest('hex');
  const ok = got && got.length === want.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(want));
  if (!ok) { throw new Error('HR-12 fan-out: HMAC signature mismatch — refusing to fan out'); }
}
const s = ev.subject || {};
const titles = { joiner: 'Provision software access (Joiner)', mover: 'Review software access (Mover)', leaver: 'Deprovision software access (Leaver)' };
const title = `[HR ${ev.event}] ${s.matricule || '?'} ${s.employee_name || ''} — ${titles[ev.event] || ev.event}`;
const content = `Lifecycle event: ${ev.event}\nMatricule: ${s.matricule}\nName: ${s.employee_name}\nEmail: ${s.email}\nJob: ${s.job}\nDepartment: ${s.department}\nEntity: ${s.entity}\nCountry: ${s.country}\nEffective: ${ev.effective_date}\nOccurred: ${ev.occurred_at}\nChange: ${JSON.stringify(ev.change || {})}\n\nNOTE: software/service provisioning only — NO hardware (BYOD). Access (Authentik groups) is handled by ktayl-iam, not here.`;
return [{ json: { event: ev.event, title, content, matricule: s.matricule, email: s.email } }];
